class Printer {
    void print(int x)    { System.out.println("int " + x); }
    void print(long x)   { System.out.println("long " + x); }     // 重载
    void print(Object o) { System.out.println("Object " + o); }

    Number value() { return 1; }
}

class ColorPrinter extends Printer {
    @Override
    void print(int x) { System.out.println("彩色 int " + x); }   // 重写

    @Override
    Integer value() { return 2; }                                 // 协变返回类型
}

public class Demo {
    public static void main(String[] args) {
        Printer p = new ColorPrinter();
        p.print(1);          // 彩色 int 1（运行期按实际类型）
        p.print(1L);         // long 1（编译期按参数类型选择重载）
        Object o = "hi";
        p.print(o);          // Object hi（按静态类型 Object 选择）
    }
}

import java.util.*;

public class EqDemo {
    static final class User {
        private final String id; private final String name;
        User(String id, String name) { this.id = id; this.name = name; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof User u)) return false;
            return id.equals(u.id);
        }
        @Override public int hashCode() { return Objects.hash(id); }  // 与 equals 使用相同字段
    }
    record Point(int x, int y) {}                                   // 自动生成 equals/hashCode

    public static void main(String[] args) {
        Integer a = 127, b = 127, c = 128, d = 128;
        System.out.println(a == b);          // true（缓存）
        System.out.println(c == d);          // false
        System.out.println(c.equals(d));     // true

        Set<User> set = new HashSet<>(List.of(new User("1", "张三")));
        System.out.println(set.contains(new User("1", "张三 改名")));   // true
        System.out.println(new Point(1, 2).equals(new Point(1, 2)));   // true
    }
}

public class BizException extends RuntimeException {
    private final String code;
    public BizException(String code, String msg) { super(msg); this.code = code; }
    public String getCode() { return code; }
}

public String readConfig(Path path) {
    try (BufferedReader r = Files.newBufferedReader(path)) {    // 自动关闭资源
        return r.readLine();
    } catch (NoSuchFileException e) {
        throw new BizException("CONFIG_MISSING", "配置文件不存在: " + path);
    } catch (IOException e) {
        throw new UncheckedIOException("读取配置失败", e);       // 保留原始异常
    }
}

@RestControllerAdvice
class GlobalHandler {
    @ExceptionHandler(BizException.class)
    ResponseEntity<Map<String, String>> biz(BizException e) {
        return ResponseEntity.badRequest().body(Map.of("code", e.getCode(), "msg", e.getMessage()));
    }
    @ExceptionHandler(Exception.class)
    ResponseEntity<Map<String, String>> other(Exception e) {
        log.error("unexpected", e);
        return ResponseEntity.internalServerError().body(Map.of("code", "SYS_ERROR", "msg", "系统繁忙"));
    }
}

import java.util.*;

public class GenericDemo {
    // 有界类型参数：擦除后为 Comparable
    static <T extends Comparable<T>> T max(List<? extends T> list) {
        T best = list.get(0);
        for (T t : list) if (t.compareTo(best) > 0) best = t;
        return best;
    }

    // PECS：src 生产数据用 extends，dest 消费数据用 super
    static <T> void copy(List<? super T> dest, List<? extends T> src) {
        for (T t : src) dest.add(t);
    }

    // 需要运行时类型时传入 Class
    static <T> T create(Class<T> clazz) throws Exception {
        return clazz.getDeclaredConstructor().newInstance();
    }

    public static void main(String[] args) throws Exception {
        System.out.println(max(List.of(3, 9, 5)));                          // 9
        List<Number> nums = new ArrayList<>();
        copy(nums, List.of(1, 2));                                          // Integer → Number
        System.out.println(new ArrayList<String>().getClass() == new ArrayList<Integer>().getClass()); // true
        StringBuilder sb = create(StringBuilder.class);
    }
}

