// 通用：根据字段名读取属性（缓存 Field，避免重复查找）
private static final Map<String, Field> FIELD_CACHE = new ConcurrentHashMap<>();

static Object readField(Object target, String name) throws IllegalAccessException {
    Field f = FIELD_CACHE.computeIfAbsent(target.getClass().getName() + "#" + name, k -> {
        try {
            Field fd = target.getClass().getDeclaredField(name);
            fd.setAccessible(true);           // 访问私有字段：破坏封装
            return fd;
        } catch (NoSuchFieldException e) { throw new IllegalArgumentException(e); }
    });
    return f.get(target);
}

