// 2. AOP 切面读取注解并执行逻辑
@Aspect @Component
public class RateLimitAspect {
    @Around("@annotation(limit)")
    public Object around(ProceedingJoinPoint pjp, RateLimit limit) throws Throwable {
        String key = limit.key().isEmpty() ? pjp.getSignature().toShortString() : limit.key();
        if (!limiter.tryAcquire(key, limit.permitsPerSecond())) {
            throw new BizException(429, "请求过于频繁");
        }
        return pjp.proceed();
    }
}

