public interface PayChannel {                 // 能力契约
    PayResult pay(Order o);
    default boolean supportRefund() { return true; }   // 新增方法不破坏实现类
}

public abstract class AbstractPayChannel implements PayChannel {   // 模板骨架
    protected final AuditLog audit;
    protected AbstractPayChannel(AuditLog a) { this.audit = a; }
    public final PayResult pay(Order o) {
        validate(o);
        PayResult r = doPay(o);                  // 子类实现可变步骤
        audit.record(o, r);
        return r;
    }
    protected abstract PayResult doPay(Order o);
}
